// 使用 window 下的方法（浏览器全局可直接调用）

document.getElementById('btnLog').onclick = function() {
  window.console.log('调试：按钮被点击！')
  document.getElementById('j1o').textContent = '✅ 已输出到 F12 控制台（按 F12 → Console 查看）'
}

document.getElementById('btnAlert').onclick = function() {
  window.alert('你好！这是一个 window.alert 弹窗')
  document.getElementById('j1o').textContent = '✅ window.alert 弹窗已弹出'
}

document.getElementById('btnWrite').onclick = function() {
  // 注意：document.write() 在页面加载后调用会覆盖全部内容！
  document.getElementById('j1o').textContent = '✅ document.write 已执行（但不推荐在加载后使用）'
}

